SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'bb_kurzzeichen_tab19', 'Bitumen-/Polymerbitumenbahn — Kurzzeichen nach DIN SPEC 20000-202 (Tab. 19)', 'Bitumen / polymer-bitumen sheet — designation per DIN SPEC 20000-202 (Tab. 19)', 'enum', NULL, false, '§6.1.1.1, Tab. 19', 'Coverage block 5 (A-070): the fourteen printed designations as a selection (SR-1 — printed options are offered, not typed); the free-text bb_bahnentyp stays for products outside the table. Options are generated from TAB19 rows at apply time.', 'verified_against_standard', 'Unter Bezugnahme auf DIN 18535-2 sind die in Tabelle 19 genannten Bitumen- und Polymerbitumenbahnen nach DIN EN 13969 in Verbindung mit DIN SPEC 20000-202, Anwendungstyp BA zu verwenden.', 'FLL-GAR-2023 gedruckte S. 78 — §6.1.1.1, Tab. 19', 'select_one', NULL, NULL, NULL, (SELECT jsonb_agg(jsonb_build_object('value', r.row_key, 'label_de', COALESCE(r.group_label || ' — ', '') || r.label_de, 'order_index', r.order_index + 1, 'regulation_reference', 'TAB19') ORDER BY r.order_index) FROM regulation_table_rows r JOIN regulation_tables t ON t.id = r.table_id WHERE t.standard_code = 'FLL-GAR-2023' AND t.edition = '2023-12' AND t.table_code = 'TAB19'), (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'bb_kurzzeichen_tab19') AND w.code = 'FLL-GAR-15' AND s.code = 'FLL-GAR-2023' AND EXISTS (SELECT 1 FROM regulation_tables t WHERE t.standard_code = 'FLL-GAR-2023' AND t.edition = '2023-12' AND t.table_code = 'TAB19');
