FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'bb_bahnenart_tab19') AND w.code = 'FLL-GAR-15' AND s.code = 'FLL-GAR-2023';
