SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'fk_stoff_tab23', 'Flüssigkunststoff — Stoff nach Tab. 23', 'Liquid-applied plastic — material per Tab. 23', 'enum', NULL, false, '§6.3.1.1, Tab. 23', 'Coverage block 5 (A-096): UP / PUR / PMMA as printed; the free-text fk_systemtyp stays.', 'verified_against_standard', 'Die Mindestschichtdicke der ausgehärteten flüssigen Abdichtung muss den Angaben der Zulassung (ETA, AbP gemäß MVV TB) entsprechen. Sie beträgt gemäß Tabelle 23 mind. 2,0 mm. Wenn die in der ETA angegebene Mindestschichtdicke höher ist, gilt der höhere Wert.', 'FLL-GAR-2023 gedruckte S. 89 — §6.3.1.1, Tab. 23', 'select_one', NULL, NULL, NULL, (SELECT jsonb_agg(jsonb_build_object('value', r.row_key, 'label_de', r.label_de, 'order_index', r.order_index + 1, 'regulation_reference', 'TAB23') ORDER BY r.order_index) FROM regulation_table_rows r JOIN regulation_tables t ON t.id = r.table_id WHERE t.standard_code = 'FLL-GAR-2023' AND t.edition = '2023-12' AND t.table_code = 'TAB23'), (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'fk_stoff_tab23') AND w.code = 'FLL-GAR-17' AND s.code = 'FLL-GAR-2023' AND EXISTS (SELECT 1 FROM regulation_tables t WHERE t.standard_code = 'FLL-GAR-2023' AND t.edition = '2023-12' AND t.table_code = 'TAB23');
