SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'fk_einlage_min_g_m2', 'Mindest-Flächengewicht der Einlage nach Tab. 23 (≥ 110 g/m²)', 'Minimum mass per unit area of the insert per Tab. 23 (≥ 110 g/m²)', 'number', 'g/m²', false, '§6.3.1.1, Tab. 23; §6.3.2', 'Coverage block 5: limit for fk_einlage_g_m2 (REQ-41, 5b).', 'verified_against_standard', 'Abdichtungen mit Flüssigkunststoffen werden i. d. R. vollflächig haftend und mindestens zweischichtig (Träger-, Deckschicht) mit Einlage ausgeführt. Dies kann durch Streichen, Rollen oder Spritzen erfolgen. Es müssen Einlagen (z. B. Glasvlies, Polyestervlies) mit einem Flächengewicht von mind. 110 g/m² eingesetzt werden.', 'FLL-GAR-2023 gedruckte S. 89 — §6.3.1.1, Tab. 23; §6.3.2', 'lookup_fill', '{"source_label":"Tab. 23 (Flächengewicht der Einlage)"}'::jsonb, '{"keys":[{"column":"stoff","from_symbol":"fk_stoff_tab23"}],"role":"limit","value":"einlage_min_g_m2","table_code":"TAB23"}'::jsonb, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
