INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, label_en, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, source_anchor, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'gtd_zugfestigkeit_kn_m', 'Zugfestigkeit der GTD (längs und quer, DIN EN ISO 10319)', 'Tensile strength of the GCL (MD and CD, DIN EN ISO 10319)', 'number', 'kN/m', false, '§5.5.1.1, Tab. 15 Zeile 8', 'Coverage block 5 (A-060): ≥ 10 kN/m (REQ-42, 5b).', 'verified_against_standard', 'Die Anforderungen in den Zeilen 2 bis 7 der Tabelle 15 können produktabhängig abweichen. Für andere Verbindungsverfahren, Bentonitarten und Oberflächenausbildungen gelten hinsichtlich Zugfestigkeit, Zugfestigkeitsdehnung, Verbundfestigkeit, Durchlässigkeitsbeiwert (kf) und Permittivität die in den Zeilen 8 bis 11 festgelegten Mindestanforderungen.', 'FLL-GAR-2023 gedruckte S. 65 — §5.5.1.1, Tab. 15 Zeile 8', 'scalar', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'gtd_zugfestigkeit_kn_m') AND w.code = 'FLL-GAR-14' AND s.code = 'FLL-GAR-2023';
