FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'gtd_zugfestigkeitsdehnung_pct') AND w.code = 'FLL-GAR-14' AND s.code = 'FLL-GAR-2023';
