SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'gtd_kf_m_s', 'Durchlässigkeitsbeiwert kf der GTD (DIN EN 16416, i = 150, ca. 27,5 kPa, d = 1 cm)', 'Permeability coefficient kf of the GCL (DIN EN 16416, i = 150, approx. 27.5 kPa, d = 1 cm)', 'number', 'm/s', false, '§5.5.1.1, Tab. 15 Zeile 10', 'Coverage block 5 (A-060): ≤ 5,0 · 10⁻¹¹ m/s (REQ-42, 5b).', 'verified_against_standard', 'Die Anforderungen in den Zeilen 2 bis 7 der Tabelle 15 können produktabhängig abweichen. Für andere Verbindungsverfahren, Bentonitarten und Oberflächenausbildungen gelten hinsichtlich Zugfestigkeit, Zugfestigkeitsdehnung, Verbundfestigkeit, Durchlässigkeitsbeiwert (kf) und Permittivität die in den Zeilen 8 bis 11 festgelegten Mindestanforderungen.', 'FLL-GAR-2023 gedruckte S. 65 — §5.5.1.1, Tab. 15 Zeile 10', 'scalar', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'gtd_kf_m_s') AND w.code = 'FLL-GAR-14' AND s.code = 'FLL-GAR-2023';
