SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'gtd_permittivitaet_m_s', 'Permittivität der GTD (DIN EN 16416, i = 150, ca. 27,5 kPa)', 'Permittivity of the GCL (DIN EN 16416, i = 150, approx. 27.5 kPa)', 'number', 'm/s', false, '§5.5.1.1, Tab. 15 Zeile 11', 'Coverage block 5 (A-060): ≤ 5,0 · 10⁻⁹ m/s as printed (REQ-42, 5b).', 'verified_against_standard', 'Die Anforderungen in den Zeilen 2 bis 7 der Tabelle 15 können produktabhängig abweichen. Für andere Verbindungsverfahren, Bentonitarten und Oberflächenausbildungen gelten hinsichtlich Zugfestigkeit, Zugfestigkeitsdehnung, Verbundfestigkeit, Durchlässigkeitsbeiwert (kf) und Permittivität die in den Zeilen 8 bis 11 festgelegten Mindestanforderungen.', 'FLL-GAR-2023 gedruckte S. 65 — §5.5.1.1, Tab. 15 Zeile 11', 'scalar', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'gtd_permittivitaet_m_s') AND w.code = 'FLL-GAR-14' AND s.code = 'FLL-GAR-2023';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, label_en, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, source_anchor, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'frischbeton_lufttemperatur_fall', 'Lufttemperatur beim Betonieren (Fall nach Tab. 9)', 'Air temperature during concreting (case per Tab. 9)', 'enum', NULL, false, '§5.3.2.1, Tab. 9', 'Coverage block 5 (A-040): the three printed cases.', 'verified_against_standard', 'Bei extrem niedrigen oder hohen Lufttemperaturen ist die Betontemperatur zu überwachen. Die Grenztemperaturen des Frischbetons nach DIN 1045-3 von mind. + 5 °C bzw. höchstens + 30 °C müssen eingehalten werden, um eine bleibende Beeinträchtigung der Frischbetoneigenschaften zu vermeiden (s. Tab. 9).', 'FLL-GAR-2023 gedruckte S. 53 — §5.3.2.1, Tab. 9', 'select_one', NULL, NULL, NULL, (SELECT jsonb_agg(jsonb_build_object('value', r.row_key, 'label_de', COALESCE(r.group_label || ' — ', '') || r.label_de, 'order_index', r.order_index + 1, 'regulation_reference', 'TAB9') ORDER BY r.order_index) FROM regulation_table_rows r JOIN regulation_tables t ON t.id = r.table_id WHERE t.standard_code = 'FLL-GAR-2023' AND t.edition = '2023-12' AND t.table_code = 'TAB9'), (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'frischbeton_lufttemperatur_fall') AND w.code = 'FLL-GAR-12' AND s.code = 'FLL-GAR-2023' AND EXISTS (SELECT 1 FROM regulation_tables t WHERE t.standard_code = 'FLL-GAR-2023' AND t.edition = '2023-12' AND t.table_code = 'TAB9');
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, label_en, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, source_anchor, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'frischbeton_temp_min_c', 'Mindesttemperatur des Frischbetons nach Tab. 9', 'Minimum fresh-concrete temperature per Tab. 9', 'number', '°C', false, '§5.3.2.1, Tab. 9', 'Coverage block 5: limit for frischbeton_temperatur_c (REQ-43, 5b); upper limit + 30 °C printed in §5.3.2.1.', 'verified_against_standard', 'Bei extrem niedrigen oder hohen Lufttemperaturen ist die Betontemperatur zu überwachen. Die Grenztemperaturen des Frischbetons nach DIN 1045-3 von mind. + 5 °C bzw. höchstens + 30 °C müssen eingehalten werden, um eine bleibende Beeinträchtigung der Frischbetoneigenschaften zu vermeiden (s. Tab. 9).', 'FLL-GAR-2023 gedruckte S. 53 — §5.3.2.1, Tab. 9', 'lookup_fill', '{"source_label":"Tab. 9 (Mindesttemperatur)"}'::jsonb, '{"keys":[{"column":"fall","from_symbol":"frischbeton_lufttemperatur_fall"}],"role":"limit","value":"frischbeton_min_c","table_code":"TAB9"}'::jsonb, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'frischbeton_temp_min_c') AND w.code = 'FLL-GAR-12' AND s.code = 'FLL-GAR-2023';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, label_en, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, source_anchor, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'frischbeton_temperatur_c', 'Frischbetontemperatur (Ist)', 'Fresh-concrete temperature (actual)', 'number', '°C', false, '§5.3.2.1, Tab. 9', 'Coverage block 5 (A-040).', 'verified_against_standard', 'Bei extrem niedrigen oder hohen Lufttemperaturen ist die Betontemperatur zu überwachen. Die Grenztemperaturen des Frischbetons nach DIN 1045-3 von mind. + 5 °C bzw. höchstens + 30 °C müssen eingehalten werden, um eine bleibende Beeinträchtigung der Frischbetoneigenschaften zu vermeiden (s. Tab. 9).', 'FLL-GAR-2023 gedruckte S. 53 — §5.3.2.1, Tab. 9', 'scalar', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'frischbeton_temperatur_c') AND w.code = 'FLL-GAR-12' AND s.code = 'FLL-GAR-2023';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, label_en, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, source_anchor, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'zementfestigkeitsklasse_tab10', 'Zementfestigkeitsklasse (Tab. 10)', 'Cement strength class (Tab. 10)', 'enum', NULL, false, '§5.3.2.1, Tab. 10', 'Coverage block 5 (A-041): the three printed rows.', 'verified_against_standard', 'Damit der Beton ein Durchfrieren unbeschadet übersteht, muss der Beton gefrierbeständig sein. Diese Gefrierbeständigkeit ist dann erreicht, wenn er mindestens eine Festigkeit von 5 N/mm² aufweist und vor Fremdwasser geschützt wird. Die dafür erforderlichen Erhärtungszeiten in Abhängigkeit von Temperatur, Wasserzementwert und Zementfestigkeitsklasse sind in Tabelle 10 angegeben.', 'FLL-GAR-2023 gedruckte S. 54 — §5.3.2.1, Tab. 10', 'select_one', NULL, NULL, NULL, (SELECT jsonb_agg(jsonb_build_object('value', r.row_key, 'label_de', r.label_de, 'order_index', r.order_index + 1, 'regulation_reference', 'TAB10') ORDER BY r.order_index) FROM regulation_table_rows r JOIN regulation_tables t ON t.id = r.table_id WHERE t.standard_code = 'FLL-GAR-2023' AND t.edition = '2023-12' AND t.table_code = 'TAB10'), (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'zementfestigkeitsklasse_tab10') AND w.code = 'FLL-GAR-12' AND s.code = 'FLL-GAR-2023' AND EXISTS (SELECT 1 FROM regulation_tables t WHERE t.standard_code = 'FLL-GAR-2023' AND t.edition = '2023-12' AND t.table_code = 'TAB10');
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, label_en, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, source_anchor, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'erhaertungszeit_tage_bei_5c', 'Erforderliche Erhärtungszeit bis zur Gefrierbeständigkeit bei 5 °C Betontemperatur (Tab. 10, w/z = 0,60)', 'Required curing time to frost resistance at 5 °C concrete temperature (Tab. 10, w/c = 0.60)', 'number', 'd', false, '§5.3.2.1, Tab. 10', 'Coverage block 5: informational fill (the table is printed for w/z = 0,60; the gate is a RULING — none staged).', 'verified_against_standard', 'Damit der Beton ein Durchfrieren unbeschadet übersteht, muss der Beton gefrierbeständig sein. Diese Gefrierbeständigkeit ist dann erreicht, wenn er mindestens eine Festigkeit von 5 N/mm² aufweist und vor Fremdwasser geschützt wird. Die dafür erforderlichen Erhärtungszeiten in Abhängigkeit von Temperatur, Wasserzementwert und Zementfestigkeitsklasse sind in Tabelle 10 angegeben.', 'FLL-GAR-2023 gedruckte S. 54 — §5.3.2.1, Tab. 10', 'lookup_fill', '{"source_label":"Tab. 10 (5 °C)"}'::jsonb, '{"keys":[{"column":"zementfestigkeitsklasse","from_symbol":"zementfestigkeitsklasse_tab10"}],"role":"value","value":"tage_bei_5c","table_code":"TAB10"}'::jsonb, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'erhaertungszeit_tage_bei_5c') AND w.code = 'FLL-GAR-12' AND s.code = 'FLL-GAR-2023';
